    Punctuation is ignored, and words are converted to lowercase.
    """

    clean_text = re.sub(r'[^\w\s]', '', text)
    words = clean_text.lower().split()

    frequency = {}
    total_words_processed = 0

    for word in words:
        if word: 
            frequency[word] = frequency.get(word, 0) + 1
            total_words_processed += 1

    print("Processed {} words from the input text.".format(total_words_processed))
    print("Found {} unique words.".format(len(frequency)))

    # Example of f-string usage in a more complex scenario
    for unique_word, count in frequency.items():
        if count > 1:
            print("The word '{}' appeared {} times.".format(unique_word, count))
        else:
            print("The word '{}' appeared once.".format(unique_word))

    if not frequency:
        print("No words found in the text: '{}'.".format(text))
    else:
        most_frequent_word = max(frequency, key=frequency.get)
        print("The most frequent word is '{}' with {} occurrences.".format(most_frequent_word, frequency[most_frequent_word]))

    return frequency

def simple_calculator(num1, operator, num2):
    """
    Performs basic arithmetic operations (+, -, *, /) on two numbers.
    Handles division by zero by returning 'Error'.
    """
    if operator == '+':
        result = num1 + num2
        return "The sum of {} and {} is {}.".format(num1, num2, result)
    elif operator == '-':
        result = num1 - num2
        return "The difference between {} and {} is {}.".format(num1, num2, result)
    elif operator == '*':
        result = num1 * num2
        return "The product of {} and {} is {}.".format(num1, num2, result)
    elif operator == '/':
        if num2 == 0:
            return "Error: Cannot divide {} by zero.".format(num1)
        result = num1 / num2
        return "The quotient of {} divided by {} is {}.".format(num1, num2, result)
    else:
        return "Error: Invalid operator '{}'. Please use +, -, *, or /.".format(operator)

