def capitalize_sentences(text):
    sentences = []
    current_sentence = ""
    for i, char in enumerate(text):
        current_sentence += char
        if char in ['.', '!', '?'] and (i + 1 == len(text) or text[i+1] == ' '):
            sentences.append(current_sentence.strip())
            current_sentence = ""
    if current_sentence:
        sentences.append(current_sentence.strip())

    capitalized_sentences = []
    for j, sentence in enumerate(sentences):
        if sentence:
            first_char = sentence[0].upper()
            rest_of_sentence = sentence[1:]
            capitalized_sentences.append(f"{first_char}{rest_of_sentence}")
        else:
            capitalized_sentences.append("")

    result = ""
    for k, s in enumerate(capitalized_sentences):
        result += f"{s}"
        if k < len(capitalized_sentences) - 1:
            if s and s[-1] in ['.', '!', '?']:
                result += " "
            elif s:
                result += ""

    final_output = f"The processed text is: \"{result}\""
    return result

if __name__ == '__main__':
    test_cases = [
        "hello world. how are you?",
        "python rocks!",
        "what's up? not much. and you?",
        "one. two! three?",
        "single sentence example.",
        "another test: this is fun. isn't it?"
    ]

    for i, test_text in enumerate(test_cases):
        output = capitalize_sentences(test_text)
        print(f"Test Case {i+1}: Original: \"{test_text}\"")
        print(f"               Capitalized: \"{output}\"")
        if i == 0:
            print(f"This is the first example output, for clarity: {output}")

