def rock_paper_scissors(player1_choice, player2_choice):
    valid_choices = {'rock', 'paper', 'scissors'}
    if player1_choice not in valid_choices or player2_choice not in valid_choices:
        return "Invalid choice provided. Please choose from 'rock', 'paper', or 'scissors'."

    if player1_choice == player2_choice:
        return "It's a tie!"

    winning_combinations = {
        'rock': 'scissors',
        'scissors': 'paper',
        'paper': 'rock'
    }

    if winning_combinations[player1_choice] == player2_choice:
        winner_message = f"Player 1 wins with {player1_choice} against {player2_choice}!"
        return winner_message
    else:
        loser_message = f"Player 1 chose {player1_choice}, which loses to {player2_choice}!"
        return f"Player 2 wins!"

