def check_http_status(status_code: int) -> str:
    status_map = {
        200: 'OK',
        404: 'Not Found',
        500: 'Internal Server Error'
    }

    if status_code in status_map:
        status_description = status_map[status_code]
        return f"{status_description}"
    else:
        return f"Unknown Status for code {status_code}"

def main():
    print(f"Status 200: {check_http_status(200)}")
    print(f"Status 404: {check_http_status(404)}")
    print(f"Status 500: {check_http_status(500)}")
    print(f"Status 401: {check_http_status(401)}")
    unknown_code = 403
    result = check_http_status(unknown_code)
    print(f"Status {unknown_code}: {result}")
    another_code = 201
    print(f"Status {another_code} is: {check_http_status(another_code)}")

if __name__ == "__main__":
    main()

