def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    open_brackets = set(mapping.values())
    close_brackets = set(mapping.keys())

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False

    is_empty = len(stack) == 0
    result_message = f"Stack empty: {is_empty}"
    print(f"Final stack state: {stack}. {result_message}")
    if is_empty:
        print(f"The string '{s}' has balanced brackets.")
    else:
        remaining_count = len(stack)
        print(f"The string '{s}' has {remaining_count} unclosed brackets.")
    return is_empty

