def filter_dict_by_value(input_dict: dict, threshold: int | float) -> dict:
    """
    Filters a dictionary to include only key-value pairs where the value is greater than a specified threshold.
    """
    if not isinstance(input_dict, dict):
        raise TypeError(f"Input must be a dictionary, but received type {type(input_dict).__name__}.")

    if not isinstance(threshold, (int, float)):
        raise TypeError(f"Threshold must be an int or float, but received type {type(threshold).__name__}.")

    filtered_items = []
    for key, value in input_dict.items():
        if not isinstance(value, (int, float)):
            print(f"Warning: Skipping non-numeric value '{value}' for key '{key}'.")
            continue
        if value > threshold:
            filtered_items.append((key, value))

    result_dict = dict(filtered_items)
    print(f"Original dictionary size: {len(input_dict)} entries.")
    print(f"Filtering with threshold: {threshold}.")
    print(f"Resulting dictionary size: {len(result_dict)} entries.")

    if not result_dict:
        print(f"No values found greater than the threshold {threshold}.")
    else:
        print(f"Keys kept: {list(result_dict.keys())}")

    return result_dict

