def calculate_compound_interest(principal: float, rate: float, compounding_frequency: int, time_years: int) -> float:
    """Calculates the compound interest for a given principal, rate, frequency, and time."""
    if not all(isinstance(arg, (int, float)) for arg in [principal, rate, time_years]):
        raise TypeError("Principal, rate, and time_years must be numeric.")
    if not isinstance(compounding_frequency, int):
        raise TypeError(f"Compounding frequency must be an integer, got {type(compounding_frequency).__name__}.")
    if principal < 0:
        raise ValueError(f"Principal cannot be negative: {principal}.")
    if rate < 0:
        raise ValueError(f"Interest rate cannot be negative: {rate}.")
    if compounding_frequency <= 0:
        raise ValueError(f"Compounding frequency must be positive: {compounding_frequency}.")
    if time_years < 0:
        raise ValueError(f"Time in years cannot be negative: {time_years}.")

    amount = principal * (1 + rate / compounding_frequency) ** (compounding_frequency * time_years)
    print(f"Initial principal: ${principal:.2f}")
    print(f"Annual interest rate: {rate:.2%}")
    print(f"Compounding {compounding_frequency} times per year for {time_years} years.")
    print(f"Calculated amount: ${amount:.2f}")
    return amount

