def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    if len(strings) == 1:
        return strings[0]

    prefix = strings[0]
    num_strings = len(strings)

    for i in range(1, num_strings):
        current_string = strings[i]
        new_prefix_length = 0
        min_len = min(len(prefix), len(current_string))

        for j in range(min_len):
            if prefix[j] == current_string[j]:
                new_prefix_length += 1
            else:
                break
        prefix = prefix[:new_prefix_length]
        if not prefix:
            return f"No common prefix among {num_strings} strings found." # f-string 1

    final_result_message = f"The longest common prefix for {num_strings} strings is '{prefix}'." # f-string 2
    if prefix == "":
        return f"No common prefix found for input: {strings}" # f-string 3
    else:
        print(f"Prefix found: {prefix}, length: {len(prefix)}") # f-string 4
