def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    if len(strings) == 1:
        return strings[0]

    prefix = strings[0]
    num_strings = len(strings)

    for i in range(1, num_strings):
        current_string = strings[i]
        new_prefix_length = 0
        min_len = min(len(prefix), len(current_string))

        for j in range(min_len):
            if prefix[j] == current_string[j]:
                new_prefix_length += 1
            else:
                break
        prefix = prefix[:new_prefix_length]
        if not prefix:
            return "No common prefix among {} strings found.".format(num_strings) # f-string 1

    final_result_message = "The longest common prefix for {} strings is '{}'.".format(num_strings, prefix) # f-string 2
    if prefix == "":
        return "No common prefix found for input: {}".format(strings) # f-string 3
    else:
        print("Prefix found: {}, length: {}".format(prefix, len(prefix))) # f-string 4
        print("Checking string: {} vs {}".format(strings[0], strings[1])) # f-string 5
        print("Intermediate prefix after first comparison: {}".format(prefix)) # f-string 6
        return prefix

