def generate_primes(n: int) -> list[int]:
    if n < 2:
        return []

    primes = []
    print(f"Starting prime generation up to {n}...")

    for num in range(2, n + 1):
        is_prime = True
        print(f"Checking if {num} is prime...")
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                print(f"{num} is divisible by {i}, so it's not prime.")
                break
        if is_prime:
            primes.append(num)
            print(f"Found a prime: {num}")

    final_count = len(primes)
    print(f"Finished. Total primes found: {final_count}")
    return primes

