def days_since(year, month, day):
    given_date = date(year, month, day)
    today = date.today()
    delta = today - given_date

    if delta.days < 0:
        raise ValueError(f"The given date {year}-{month:02d}-{day:02d} is in the future.")

    print(f"Calculating days between {given_date.isoformat()} and {today.isoformat()}.")

    if delta.days == 0:
        print(f"The given date is today: {today.isoformat()}.")
    else:
        print(f"It has been {delta.days} days since {year}-{month:02d}-{day:02d}.")

    return delta.days

