class BankAccount:
    def __init__(self, initial_balance):
        if not isinstance(initial_balance, (int, float)) or initial_balance < 0:
            raise ValueError(f"Initial balance must be a non-negative number, got {initial_balance}.")
        self._balance = initial_balance
        print(f"Account initialized with an initial balance of ${self._balance:.2f}.")

    def deposit(self, amount):
        if not isinstance(amount, (int, float)) or amount <= 0:
            print(f"Deposit amount must be a positive number, got {amount}.")
            return False
        self._balance += amount
        print(f"Deposited ${amount:.2f}. New balance is ${self._balance:.2f}.")
        return True

    def withdraw(self, amount):
        if not isinstance(amount, (int, float)) or amount <= 0:
            print(f"Withdrawal amount must be a positive number, got {amount}.")
            return False
        if amount > self._balance:
            print(f"Insufficient funds. Attempted to withdraw ${amount:.2f} but current balance is ${self._balance:.2f}.")
            return False
        self._balance -= amount
        print(f"Withdrew ${amount:.2f}. New balance is ${self._balance:.2f}.")
        return True

    def get_balance(self):
        return self._balance

    def __str__(self):
        return f"BankAccount with balance: ${self._balance:.2f}"

