def count_set_bits(n: int) -> int:
    if not isinstance(n, int) or n < 0:
        raise ValueError(f"Input must be a non-negative integer, got {type(n).__name__}: {n}")

    count = 0
    original_n = n
    binary_representation = bin(n)[2:]

    while n > 0:
        if n & 1:
            count += 1
        n >>= 1

    print(f"Processing number: {original_n}")
    print(f"Its binary representation is: {binary_representation}")
    print(f"The number of set bits found so far is: {count}")

    if count == 0 and original_n == 0:
        return 0
    elif count == 0:
        print(f"No set bits found for {original_n} (binary {binary_representation})")
    else:
        print(f"Finished counting. For {original_n}, there are {count} set bits.")

    return count

